        "how": "check logs for errors",
        "expected": "no errors present"
      }
    },
    {
      "id": "dual-ship",
      "description": "Configure dual shipping to send logs to both Fluentd and FluentBit",
      "action": "configure",
      "target": "log shipping",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "FluentBit is deployed",
          "fact": "fluentbit_deployed",
          "established_by": "deploy-fluentbit"
        }
      ],
      "verification": {
        "what": "verify dual shipping setup",
        "how": "check configuration settings",
        "expected": "configuration correctly set for dual shipping"
