      "description": "Remove FluentD from nodes",
      "action": "cleanup",
      "target": "FluentD",
      "risk_class": "medium",
      "preconditions": [
        {
          "description": "Cutover was successful",
          "fact": "cutover_successful",
          "established_by": "cutover"
        }
      ],
      "verification": {
        "what": "confirm FluentD is removed",
        "how": "check node service status",
        "expected": "FluentD service no longer running"
      }
    }
  ],
  "dependencies": [
    {
      "from_task": "deploy-fluentbit",
