    },
    {
      "from_task": "verify-fluentbit",
      "to_task": "dual-ship",
      "kind": "hard"
    },
    {
      "from_task": "dual-ship",
      "to_task": "compare-logs",
      "kind": "hard"
    },
    {
      "from_task": "compare-logs",
